CREATE DATABASE IF NOT EXISTS examforge DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE examforge;
CREATE TABLE IF NOT EXISTS sys_user(id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(64) NOT NULL UNIQUE,password VARCHAR(100) NOT NULL,display_name VARCHAR(100) NOT NULL,role VARCHAR(20) NOT NULL,status TINYINT NOT NULL DEFAULT 1,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_user_role_status(role,status))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS question_bank(id BIGINT PRIMARY KEY AUTO_INCREMENT,type VARCHAR(20) NOT NULL,content TEXT NOT NULL,options_json JSON NULL,correct_answer TEXT NOT NULL,analysis TEXT NULL,difficulty VARCHAR(20) DEFAULT 'MEDIUM',knowledge_point VARCHAR(255) NULL,default_score DECIMAL(8,2) NOT NULL DEFAULT 1,created_by BIGINT NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_question_type(type),KEY idx_question_kp(knowledge_point))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS exam(id BIGINT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(200) NOT NULL,description TEXT NULL,status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',start_time DATETIME NOT NULL,end_time DATETIME NOT NULL,duration_minutes INT NOT NULL,created_by BIGINT NOT NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_exam_status_time(status,start_time,end_time))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS exam_question(id BIGINT PRIMARY KEY AUTO_INCREMENT,exam_id BIGINT NOT NULL,question_id BIGINT NOT NULL,sort_order INT NOT NULL,score DECIMAL(8,2) NOT NULL,UNIQUE KEY uk_exam_question(exam_id,question_id),KEY idx_exam_order(exam_id,sort_order),CONSTRAINT fk_eq_exam FOREIGN KEY(exam_id)REFERENCES exam(id)ON DELETE CASCADE,CONSTRAINT fk_eq_question FOREIGN KEY(question_id)REFERENCES question_bank(id))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS exam_attempt(id BIGINT PRIMARY KEY AUTO_INCREMENT,exam_id BIGINT NOT NULL,user_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL,started_at DATETIME NOT NULL,deadline_at DATETIME NOT NULL,submitted_at DATETIME NULL,question_snapshot JSON NOT NULL,version INT NOT NULL DEFAULT 0,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_exam_user(exam_id,user_id),KEY idx_attempt_status_deadline(status,deadline_at),KEY idx_attempt_user(user_id,create_time),CONSTRAINT fk_attempt_exam FOREIGN KEY(exam_id)REFERENCES exam(id),CONSTRAINT fk_attempt_user FOREIGN KEY(user_id)REFERENCES sys_user(id))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS answer_record(id BIGINT PRIMARY KEY AUTO_INCREMENT,attempt_id BIGINT NOT NULL,question_id BIGINT NOT NULL,answer TEXT NULL,version INT NOT NULL DEFAULT 0,score DECIMAL(8,2) NULL,teacher_comment TEXT NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_attempt_question(attempt_id,question_id),KEY idx_answer_attempt(attempt_id),CONSTRAINT fk_answer_attempt FOREIGN KEY(attempt_id)REFERENCES exam_attempt(id)ON DELETE CASCADE,CONSTRAINT fk_answer_question FOREIGN KEY(question_id)REFERENCES question_bank(id))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS outbox_event(id BIGINT PRIMARY KEY AUTO_INCREMENT,event_key VARCHAR(128) NOT NULL UNIQUE,event_type VARCHAR(32) NOT NULL,payload JSON NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',retry_count INT NOT NULL DEFAULT 0,deliver_at DATETIME NULL,next_retry_at DATETIME NULL,published_at DATETIME NULL,last_error VARCHAR(500) NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_outbox_status_retry(status,next_retry_at))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS grade_result(id BIGINT PRIMARY KEY AUTO_INCREMENT,attempt_id BIGINT NOT NULL UNIQUE,exam_id BIGINT NOT NULL,user_id BIGINT NOT NULL,objective_score DECIMAL(10,2) NOT NULL DEFAULT 0,subjective_score DECIMAL(10,2) NOT NULL DEFAULT 0,total_score DECIMAL(10,2) NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL,graded_at DATETIME NULL,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_grade_user(user_id,graded_at),KEY idx_grade_status(status),CONSTRAINT fk_grade_attempt FOREIGN KEY(attempt_id)REFERENCES exam_attempt(id),CONSTRAINT fk_grade_exam FOREIGN KEY(exam_id)REFERENCES exam(id),CONSTRAINT fk_grade_user FOREIGN KEY(user_id)REFERENCES sys_user(id))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
